function uid(){return Math.random().toString(36).slice(2,10);}
function safeId(v){const s=String(v==null?'':v).replace(/[^A-Za-z0-9_-]/g,'').slice(0,64);return s||uid();}
function escapeHTML(s){return String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function esc(s){return escapeHTML(s);}
function todayISO(){return new Date().toISOString().slice(0,10);}
function fmtBRL(v){const neg=v<0;v=Math.abs(v);return(neg?'-':'')+'R$ '+v.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});}
function fmtDate(iso){const[y,m,d]=iso.split('-');return d+'/'+m+'/'+y;}
function monthKey(iso){return iso.slice(0,7);}
function monthLabel(key){const[y,m]=key.split('-').map(Number);return new Date(y,m-1,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'});}
function capitalize(s){return s.charAt(0).toUpperCase()+s.slice(1);}
