function iconColorFor(hex){
  const n=parseInt(hex.slice(1),16);
  const lum=(0.2126*(n>>16)+0.7152*((n>>8)&255)+0.0722*(n&255))/255;
  return lum>0.55?'rgba(16,24,40,0.78)':'#ffffff';
}
function brandFor(desc){
  const d=(desc||'').toLowerCase(),n=d.replace(/[^a-z0-9]/g,'');
  for(const b of BRANDS){for(let k=0;k<b.keys.length;k++){if(d.indexOf(b.keys[k])>-1||n.indexOf(b.keys[k])>-1)return b;}}
  return null;
}
