function openTxPage(){const b=document.querySelector('.nav-item[data-page="transacoes"]');if(b)b.click();}
function brandOrCat(desc,catId){
  const br=brandFor(desc),c=catInfo(catId);
  return br?('<span class="brand-ico'+(br.vb?' bi-ff':'')+'"><svg viewBox="'+(br.vb||'0 0 24 24')+'" fill="'+(br.f||'#000')+'">'+br.g+'</svg></span>')
           :('<span class="cat-icon" style="background:'+c.cor+';color:'+iconColorFor(c.cor)+'">'+catIconSVG(catId)+'</span>');
}
function allCats(){return CATS.concat(INCOME_CATS).concat(state.cats||[]);}
function allCatsList(){if(!state.cats)state.cats=[];return CATS.concat(state.cats);}
function catInfoByName(nome){return allCats().find(c=>c.nome.toLowerCase()===nome.toLowerCase());}
const CAT_COLORS=['#E05252','#E07C52','#E0A752','#E0D252','#C4E052','#99E052','#6EE052','#52E060','#52E08B','#52E0B6','#52E0E0','#52B6E0','#528BE0','#5260E0','#6E52E0','#9952E0','#C452E0','#E052D2','#E052A7','#9CA3AF'];
function accName(id){const a=state.accounts.find(x=>x.id===id);if(a)return a.nome;const c=state.cards.find(x=>x.id===id);if(c)return c.nome;return '—';}
function currentMonthKey(){return new Date().toISOString().slice(0,7);}
function daysInMonth(y,m){return new Date(y,m+1,0).getDate();}
function ymdLocal(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function easterSunday(y){const a=y%19,b=Math.floor(y/100),c=y%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451);return new Date(y,Math.floor((h+l-7*m+114)/31)-1,((h+l-7*m+114)%31)+1);}
const BR_FIXED_HOLIDAYS=['01-01','04-21','05-01','09-07','10-12','11-02','11-15','11-20','12-25'];
const _brHolidays={};
function brHolidaySet(y){if(_brHolidays[y])return _brHolidays[y];const s=new Set(BR_FIXED_HOLIDAYS.map(x=>y+'-'+x));const e=easterSunday(y);const add=off=>{s.add(ymdLocal(new Date(e.getFullYear(),e.getMonth(),e.getDate()+off)));};add(-48);add(-47);add(-2);add(60);_brHolidays[y]=s;return s;}
function isBusinessDay(d){const w=d.getDay();if(w===0||w===6)return false;return !brHolidaySet(d.getFullYear()).has(ymdLocal(d));}
function nthBusinessDay(y,m,n){let c=0;const dim=daysInMonth(y,m);for(let day=1;day<=dim;day++){const d=new Date(y,m,day);if(isBusinessDay(d)){c++;if(c===n)return d;}}return new Date(y,m,dim);}
function incomeDate(inc,y,m){const q=(inc&&inc.quando)||'dia-fixo';if(q==='quinto-dia-util')return nthBusinessDay(y,m,5);if(q==='ultimo-dia')return new Date(y,m,daysInMonth(y,m));const day=Math.min(Math.max(1,parseInt(inc&&inc.dia,10)||1),daysInMonth(y,m));return new Date(y,m,day);}
function nextIncomeDate(inc,from){from=from||new Date();const t0=new Date(from.getFullYear(),from.getMonth(),from.getDate());let d=incomeDate(inc,t0.getFullYear(),t0.getMonth());if(d<t0){const nm=new Date(t0.getFullYear(),t0.getMonth()+1,1);d=incomeDate(inc,nm.getFullYear(),nm.getMonth());}return d;}
const INCOME_QUANDO_LABEL={'quinto-dia-util':'5º dia útil','ultimo-dia':'Último dia do mês','dia-fixo':'Dia fixo'};
function incomeSchedLabel(inc){const q=(inc&&inc.quando)||'dia-fixo';if(q==='dia-fixo')return 'Todo dia '+((inc&&inc.dia)||1);if(q==='quinto-dia-util')return '5º dia útil do mês';return 'Último dia do mês';}
function incomeNext(inc){const d=nextIncomeDate(inc);const now=new Date();const t0=new Date(now.getFullYear(),now.getMonth(),now.getDate());const dd=Math.round((new Date(d.getFullYear(),d.getMonth(),d.getDate())-t0)/86400000);return {date:d,dd,label:dd===0?'Hoje':(dd===1?'Amanhã':'Em '+dd+' dias'),tag:dd===0?'hoje':(dd===1?'amanhã':dd+'d')};}

const LS_KEY='cofre_financas_v4';
function emptyState(){
  return{accounts:[],cards:[],subs:[],incomes:[],tx:[],cats:[],watchlist:['PETR4','VALE3','ITUB4','MGLU3'],brapiToken:'',
    nome:'',moeda:'BRL',diaSalario:null,objetivo:'controlar-gastos',
    contas:[], // will be populated from step 2
    cartoes:[], // will be populated from step 3
    rendaLiquido:0,frequencia:'mensal',dataRecebimento:'',rendaVariavel:0,
    parcelas:[], // will be populated from step 5
    gastos:{assinaturas:[],fixos:[],variaveis:[]}, // will be populated from step 6
    objetivos:{metaEconomizar:0,metaReserva:0,objetivoFuturo:'',prazoObjetivo:'',minimoDisponivel:0} // will be populated from step 7
  };
}

let state=loadState();
function loadState(){try{const raw=localStorage.getItem(LS_KEY);if(raw){let s=null;try{s=JSON.parse(raw);}catch(pe){window.__stateCorrupt=true;console.error('Dados salvos corrompidos:',pe);}if(s){if(typeof s==='object'&&Array.isArray(s.accounts))return sanitizeState(s);window.__stateCorrupt=true;}}}catch(e){console.error('Falha ao carregar dados salvos:',e);}return emptyState();}
function saveState(){try{localStorage.setItem(LS_KEY,JSON.stringify(state));}catch(e){console.error('Falha ao salvar dados:',e);toastError('Não foi possível salvar os dados.');}}
function snapshotState(){try{return JSON.parse(JSON.stringify(state));}catch(e){return null;}}
function restoreState(snap){if(!snap)return;state=snap;saveState();renderAll();}
let THEME=(()=>{try{return localStorage.getItem('cofre_theme_v1')||'light';}catch(e){return 'light';}})();

document.querySelectorAll('.nav-item').forEach(btn=>{
  btn.addEventListener('click',()=>{
    document.querySelectorAll('.nav-item').forEach(b=>{b.classList.remove('active');b.removeAttribute('aria-current');});
    btn.classList.add('active');
    btn.setAttribute('aria-current','page');
    document.querySelectorAll('.page').forEach(p=>p.classList.add('hidden'));
    const page=document.getElementById('page-'+btn.dataset.page);
    page.classList.remove('hidden');
    page.classList.add('fade-in');
    document.body.classList.toggle('cc-open',btn.dataset.page==='cartoes');
    openDrawer(false);
    renderAll();
    if(btn.dataset.page==='investimentos')loadMarketData();
  });
});
function openDrawer(open){
  const sb=document.getElementById('sidebar'),sc=document.getElementById('scrim');
  if(sb)sb.classList.toggle('open',open);
  if(sc)sc.classList.toggle('open',open);
  const mt=document.getElementById('menuToggle');
  if(mt){mt.setAttribute('aria-expanded',open?'true':'false');mt.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');}
}
document.getElementById('menuToggle').addEventListener('click',()=>{const sb=document.getElementById('sidebar');openDrawer(sb?!sb.classList.contains('open'):false);});
document.getElementById('scrim').addEventListener('click',()=>openDrawer(false));
document.addEventListener('keydown',e=>{if(e.key==='Escape')openDrawer(false);});

function toast(msg,opts){
  const t=document.getElementById('toast');if(!t)return;
  const msgEl=document.getElementById('toastMsg');if(msgEl)msgEl.textContent=msg;
  const isError=opts==='error'||(opts&&opts.type==='error');
  t.setAttribute('aria-live',isError?'assertive':'polite');
  t.classList.toggle('toast-error',isError);
  const actionBtn=document.getElementById('toastAction');
  const action=opts&&opts.action;
  if(actionBtn){
    if(typeof action==='function'){
      actionBtn.hidden=false;
      actionBtn.onclick=()=>{actionBtn.hidden=true;clearTimeout(window._toastTimer);t.classList.remove('show');try{action();}catch(e){console.error('Falha ao desfazer:',e);toastError('Não foi possível desfazer.');}};
    }else{actionBtn.hidden=true;actionBtn.onclick=null;}
  }
  t.classList.add('show');
  clearTimeout(window._toastTimer);
  window._toastTimer=setTimeout(()=>{t.classList.remove('show');if(actionBtn)actionBtn.hidden=true;},typeof action==='function'?5200:2600);
}
function toastError(msg){toast(msg,{type:'error'});}
function showFieldError(el,msg){
  if(!el)return;
  el.setAttribute('aria-invalid','true');
  let err=el._errEl;
  if(!err||!err.parentNode){
    err=document.createElement('p');err.className='field-err';
    err.id=(el.id||('field'+Math.random().toString(36).slice(2,7)))+'-err';
    el._errEl=err;
    if(el.parentNode)el.parentNode.appendChild(err);
  }
  err.textContent=msg;
  el.setAttribute('aria-describedby',err.id);
}
function clearFieldError(el){if(!el)return;el.removeAttribute('aria-invalid');el.removeAttribute('aria-describedby');if(el._errEl&&el._errEl.parentNode)el._errEl.parentNode.removeChild(el._errEl);el._errEl=null;}
function clearFieldErrors(scope){if(!scope)return;scope.querySelectorAll('[aria-invalid="true"]').forEach(clearFieldError);}

