function showFatalError(o){
  o=o||{};
  const s=document.getElementById('fatalScreen');if(!s)return;
  const t=document.getElementById('fatalTitle');if(t)t.textContent=o.title||'Algo deu errado';
  const d=document.getElementById('fatalDesc');if(d)d.textContent=o.desc||'Não foi possível carregar o aplicativo. Tente recarregar a página.';
  const rel=document.getElementById('fatalReload');if(rel)rel.onclick=()=>location.reload();
  const sec=document.getElementById('fatalSecondary');
  if(sec){
    if(o.secondary&&o.secondary.label){sec.hidden=false;sec.textContent=o.secondary.label;sec.onclick=()=>{try{o.secondary.onClick();}catch(e){console.error('Falha na ação de recuperação:',e);}};}
    else{sec.hidden=true;sec.onclick=null;}
  }
  const w=document.getElementById('welcomeScreen');if(w){w.classList.add('hidden');w.setAttribute('aria-hidden','true');}
  s.hidden=false;
  if(rel)try{rel.focus();}catch(e){}
}
