  if(gEl){const nm=(state.nome||'').trim().split(/\s+/)[0]||'por aqui';gEl.textContent=(h<12?'Bom dia':(h<18?'Boa tarde':'Boa noite'))+', '+nm+'.';}

  catOut=catPairs(mtx.filter(t=>t.valor>0&&!t.liq));
  catIn=catPairs(mtx.filter(t=>t.valor<0&&!t.liq));
  const upcoming=getUpcomingBills(15);const upcomingTotal=upcoming.reduce((s,b)=>s+b.valor,0);
  const recent=recentTxList(7);
