function hexA(hex,a){
  const v=parseInt(hex.slice(1),16);
  return 'rgba('+((v>>16)&255)+','+((v>>8)&255)+','+(v&255)+','+a+')';
}
function statusIconSVG(state){
  const by={
    good:'<path d="M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1 1 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z"/><path d="m9 12 2 2 4-4"/>',
    warn:'<path d="M21.73 18 13.73 4a2 2 0 0 0-3.46 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"/><path d="M12 9v4"/><path d="M12 17h.01"/>',
    bad:'<path d="M7.86 2h8.28L22 7.86v8.28L16.14 22H7.86L2 16.14V7.86z"/><path d="M12 8v4"/><path d="M12 16h.01"/>'
  };
  return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'+(by[state]||by.good)+'</svg>';
}
function saldoSeries(hs){
  const now=new Date(),cy=now.getFullYear(),cm=now.getMonth();
  const saldo=Math.max(totalSaldo(),50);
  const slope=hs==='bad'?-0.06:(hs==='warn'?-0.01:0.03);
  const jitter=hs==='bad'?0.014:(hs==='warn'?0.022:0.03);
  const months=8,labels=[],vals=[];
  const w=t=>Math.sin(t*0.9+1.7)+0.6*Math.sin(t*2.3+0.5)+0.25*Math.sin(t*4.1+1.1);
  const v=t=>saldo*(1+slope*t)+saldo*jitter*(w(t)-w(0));
  for(let i=0;i<months;i++){
    labels.push(capitalize(new Date(cy,cm-(months-1-i),1).toLocaleDateString('pt-BR',{month:'long'})));
    vals.push(Math.round(v(i-months+1)));
  }
  for(let k=1;k<=3;k++){
    labels.push(capitalize(new Date(cy,cm+k,1).toLocaleDateString('pt-BR',{month:'long'})));
    vals.push(Math.round(v(k)));
  }
  return {labels,vals,todayIdx:months-1};
}
const saldoWipePlugin={
  id:'saldoWipe',
  beforeDatasetsDraw(chart,e,opts){
    const w=chart.$wipe;
    if(w===undefined||w>=1)return;
    const ctx=chart.ctx;
    ctx.save();ctx.beginPath();ctx.rect(0,0,chart.canvas.width*w,chart.canvas.height);ctx.clip();
  },
  afterDatasetsDraw(chart,e,opts){
    if(chart.$wipe!==undefined&&chart.$wipe<1)chart.ctx.restore();
  }
};
const saldoGlowPlugin={
  id:'saldoGlow',
  afterDatasetsDraw(chart,e,opts){
    if(!chart.$wipe||chart.$wipe<1)return;
    const x=chart.scales.x.getPixelForValue(opts.idx);
    const y=chart.scales.y.getPixelForValue(opts.val);
    const ctx=chart.ctx,c=opts.color;
    ctx.save();
    const g=ctx.createRadialGradient(x,y,0,x,y,18);
    g.addColorStop(0,hexA(c,0.6));g.addColorStop(1,hexA(c,0));
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,18,0,Math.PI*2);ctx.fill();
    ctx.lineWidth=2.5;ctx.strokeStyle=c;ctx.beginPath();ctx.arc(x,y,4,0,Math.PI*2);ctx.stroke();
    ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(x,y,4,0,Math.PI*2);ctx.fill();
    ctx.restore();
  }
};
function renderSaldoChart(){
  const el=document.getElementById('saldoTrendChart');
  if(!el)return;
  if(!window.Chart){const box=el.closest('.sc-chart');if(box)box.innerHTML=chartUnavailableHTML();return;}
  const panel=document.querySelector('.saldo-card');
  const health=getComputedStyle(panel).getPropertyValue('--health').trim()||'#0b7a56';
  const hs=panel.classList.contains('health-bad')?'bad':(panel.classList.contains('health-warn')?'warn':'good');
  const {labels,vals,todayIdx}=saldoSeries(hs);
  const data=vals;
  const yMin=Math.min.apply(null,data),yMax=Math.max.apply(null,data),yScale=Math.max(Math.abs(yMin),Math.abs(yMax),1);
  const span=Math.max(yMax-yMin,yScale*0.07,1);
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const grim=el.getContext('2d').createLinearGradient(0,0,0,el.clientHeight||200);
  grim.addColorStop(0,hexA(health,0.2));grim.addColorStop(1,hexA(health,0.01));
  if(saldoChart)saldoChart.destroy();
  const chart=new Chart(el,{
    type:'line',
    data:{labels,datasets:[{data,borderColor:health,borderWidth:2,pointRadius:0,tension:.4,fill:'origin',backgroundColor:grim,borderJoinStyle:'round'}]},
    plugins:[saldoWipePlugin,saldoGlowPlugin],
    options:{
      responsive:true,maintainAspectRatio:false,
      animation:reduced?false:{duration:1000,easing:'easeOutQuart'},
      interaction:{mode:'index',intersect:false},
      plugins:{
        legend:{display:false},
        tooltip:{enabled:false},
        saldoWipe:{},
        saldoGlow:{idx:todayIdx,val:data[todayIdx],color:health}
      },
      scales:{x:{display:false},y:{display:false,min:yMin-span*0.25,max:yMax+span*1.4}},
      layout:{padding:{right:6}},
      elements:{point:{radius:0,hoverRadius:0}}
    }
  });
  saldoChart=chart;
  chart.$wipe=reduced?1:0;
  if(chart.$wipe>=1){chart.draw();return;}
  const t0=performance.now(),dur=1100;
  (function step(now){
    const p=Math.min(1,(now-t0)/dur);
    chart.$wipe=1-Math.pow(1-p,4);
    chart.draw();
    if(p<1)requestAnimationFrame(step);
  })(performance.now());
}

function catPairs(txs){
  const by={};txs.forEach(t=>{by[t.categoria]=(by[t.categoria]||0)+Math.abs(t.valor);});
  return Object.entries(by).sort((a,b)=>b[1]-a[1]);
}
function switchDonut(mode){
  donutMode=(mode==='in'?'in':'out');
  renderDonut();
}
function renderDonut(){
  const arr=donutMode==='in'?catIn:catOut;
  const isIn=donutMode==='in';
  const title=document.getElementById('donutTitle');
  if(title)title.textContent=isIn?'Ganhos por categoria':'Gastos por categoria';
  const sub=document.getElementById('donutSub');
  if(sub)sub.textContent=isIn?(arr.length?'De onde o dinheiro veio neste mês':'Sem ganhos registrados neste mês'):(arr.length?'Onde o dinheiro está indo neste mês':'Sem gastos registrados neste mês');
  const total=arr.reduce((s,x)=>s+x[1],0);
  const leg=document.getElementById('donutLegend');
  if(leg)leg.innerHTML=arr.length?arr.map(([id,val])=>{const c=catInfo(id);const pct=Math.round((val/total)*100);return '<div class="cat-row"><span class="swatch" style="background:'+c.cor+'"></span><span class="name">'+esc(c.nome)+'</span><span class="pct">'+pct+'%</span><span class="val">'+fmtBRL(val)+'</span></div>';}).join(''):'<p style="color:var(--ink-faint);font-size:0.85rem;">Nenhum registro por enquanto.</p>';
  const seg2=document.getElementById('donutSeg');
  if(seg2)seg2.classList.toggle('seg-in',isIn);
  document.querySelectorAll('#donutSeg .seg-btn').forEach(b=>b.classList.toggle('active',b.dataset.mode===donutMode));
  renderDonutChart(arr,total);
}
function renderDonutChart(arr,total){
  const canvas=document.getElementById('donutCanvas');
  if(!canvas)return;
  if(!window.Chart){const wrap=canvas.closest('.donut-wrap');if(wrap)wrap.innerHTML=chartUnavailableHTML();return;}
  if(donutChart){donutChart.destroy();donutChart=null;}
  const totEl=document.getElementById('donutTotal');
  if(!arr.length){if(totEl)totEl.textContent='R$ 0,00';return;}
  donutChart=new Chart(canvas,{type:'doughnut',data:{labels:arr.map(([id])=>catInfo(id).nome),datasets:[{data:arr.map(([,v])=>v),backgroundColor:arr.map(([id])=>catInfo(id).cor),borderWidth:0,hoverOffset:6}]},options:{cutout:'68%',responsive:true,maintainAspectRatio:false,animation:{duration:450,easing:'easeOutQuart'},plugins:{legend:{display:false},tooltip:{backgroundColor:THEME==='dark'?'#161c23':'#ffffff',titleColor:THEME==='dark'?'#e6e9ef':'#111827',bodyColor:THEME==='dark'?'#a4acb7':'#4b5563',borderColor:THEME==='dark'?'#242d37':'#e6e8ec',borderWidth:1,padding:12,cornerRadius:8,titleFont:{family:'Outfit',size:13,weight:'600'},bodyFont:{family:'Outfit',size:12},callbacks:{title:function(items){return items.length?items[0].label:'';},label:function(ctx){return ' '+fmtBRL(ctx.raw);}}}}}});
  if(totEl)animateNumber(totEl,total,'R$ ',2);
}

const A_ICON_WARN='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3L2 20h20z"/><path d="M12 10v4M12 17h.01"/></svg>';
const A_ICON_OK='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M8.5 12.5l2.5 2.5 4.5-5"/></svg>';
function dashAlertHTML(upcoming,saidas,saidasPrev){
  const b=(tone,title,msg)=>'<div class="dash-alert '+tone+'"><span class="da-ico">'+(tone==='ok'?A_ICON_OK:A_ICON_WARN)+'</span><div class="da-body"><div class="da-title">'+title+'</div><div class="da-msg">'+msg+'</div></div></div>';
  if(upcoming.length){
    const over=upcoming.filter(x=>x.data<todayISO());
    if(over.length){
      const n=over.length;
      return b('danger','Pagamento'+(n===1?' atrasado':'s atrasados'),'<b>'+fmtBRL(over.reduce((s,x)=>s+x.valor,0))+'</b> em '+n+' conta'+(n===1?'':'s')+'. Revise em Transações.');
    }
  }
  if(saidasPrev>0){
    const d=Math.round(((saidas-saidasPrev)/saidasPrev)*100);
    if(d>8)return b('warn','Gastos subindo','Você está gastando <b>'+d+'%</b> a mais do que no mês passado.');
    if(d<-8)return b('ok','No ritmo','Você gastou <b>'+Math.abs(d)+'%</b> menos do que no mês passado.');
  }
  return '';
}
function dashIncomeHTML(){
  const list=(state.incomes||[]);
  if(!list.length)return '';
  const up=list.map(i=>({i,ni:incomeNext(i)})).filter(x=>x.ni.dd>=0&&x.ni.dd<=15).sort((a,b)=>a.ni.dd-b.ni.dd);
  if(!up.length)return '';
  const totalMes=list.reduce((s,i)=>s+Math.abs(i.valor||0),0);
  const first=up[0];
  const when=first.ni.dd===0?'hoje':(first.ni.dd===1?'amanhã':'em '+first.ni.dd+' dias');
  const extra=up.length>1?(' Mais '+(up.length-1)+' recebimento'+(up.length-1===1?'':'s')+' nos próximos 15 dias.'):'';
  return '<div class="dash-alert ok"><span class="da-ico">'+A_ICON_OK+'</span><div class="da-body"><div class="da-title">Recebimento próximo</div><div class="da-msg"><b>'+esc(first.i.nome)+'</b> ('+fmtBRL(first.i.valor)+') cai '+when+'. Previsto no mês: <b>'+fmtBRL(totalMes)+'</b>.'+extra+'</div></div></div>';
}
