function bankFor(nome){
  const n=String(nome||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'');
  for(const b of BANKS){for(const k of b.k){if(n.indexOf(k.replace(/[^a-z0-9]/g,''))>-1)return b;}}
  return null;
}
function bankIco(nome){
  const b=bankFor(nome);
  if(!b)return null;
  return '<span class="brand-ico ac-ico'+(b.vb?' bi-ff':'')+'"'+(b.tile?' style="background:'+b.tile+'"':'')+'><svg viewBox="'+(b.vb||'0 0 24 24')+'" fill="'+(b.f||'#000')+'">'+b.g+'</svg></span>';
}

function ccBankIco(nome){
  const b=bankFor(nome);
  if(!b)return null;
  return '<span class="brand-ico cc-banklogo'+(b.vb?' bi-ff':'')+'"'+(b.tile?' style="background:'+b.tile+'"':'')+'><svg viewBox="'+(b.vb||'0 0 24 24')+'" fill="'+(b.f||'#000')+'">'+b.g+'</svg></span>';
}
const ACC_TINT={corrente:{bg:'rgba(78,141,224,0.16)',c:'#4E8DE0'},poupanca:{bg:'rgba(47,181,107,0.16)',c:'#2FB56B'},investimento:{bg:'rgba(139,92,246,0.18)',c:'#8B5CF6'}};
function accIco(a){
  const bi=bankIco(a.nome);
  if(bi)return bi;
  const t=ACC_TINT[a.tipo]||ACC_TINT.corrente;
  return '<span class="ac-ico ac-ini" style="color:'+t.c+';background:'+t.bg+'">'+initials(a.nome)+'</span>';
}
function subPaidThisMonth(s){
  const mk=currentMonthKey();
  return state.tx.some(t=>t.src==='sub'&&t.srcId===s.id&&monthKey(t.data)===mk);
}
function chargeOf(s){
  const now=new Date();let d=new Date(now.getFullYear(),now.getMonth(),s.dia);if(d<now)d=new Date(now.getFullYear(),now.getMonth()+1,s.dia);
  const dd=Math.ceil((d-now)/86400000);
  return {date:d.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'}),dd,stamp:d.getTime(),label:dd===0?'Vence hoje':(dd===1?'Vence amanhã':'Vence em '+dd+' dias'),tag:dd===0?'hoje':(dd===1?'amanhã':dd+'d')};
}
const ACCT_LABEL={corrente:'Conta corrente',poupanca:'Poupança',investimento:'Investimento'};
function renderAssinaturas(){
  const paid=s=>subPaidThisMonth(s);
  const subs=state.subs.slice();
  const aPagar=subs.filter(s=>!paid(s)).sort((a,b)=>chargeOf(a).stamp-chargeOf(b).stamp);
  const pagas=subs.filter(paid);
  const proxima=aPagar[0]||null;
  const totalMes=aPagar.reduce((s,x)=>s+x.valor,0);
  const totalAss=subs.reduce((s,x)=>s+x.valor,0);
  document.getElementById('subsSub').textContent=subs.length?(aPagar.length?(aPagar.length+' assinatura'+(aPagar.length===1?'':'s')+' a pagar este mês, somando '+fmtBRL(totalMes)+'.'):'Todas as '+pagas.length+' assinaturas pagas este mês.'):'Nenhuma assinatura cadastrada ainda.';
  document.getElementById('subsSummary').innerHTML='<div class="hero-bill"><div class="hb-main"><span class="hb-eyebrow">'+(aPagar.length?'a pagar neste mês':'assinaturas do mês')+'</span><span class="hb-total">'+fmtBRL(aPagar.length?totalMes:totalAss)+'</span><span class="hb-note">'+(aPagar.length?('São '+aPagar.length+' de '+subs.length+' assinaturas aguardando pagamento.'):(subs.length?'Tudo em dia. Nenhuma cobrança pendente este mês.':'Adicione a primeira assinatura para começar.'))+'</span></div><div class="hb-side">'
    +'<div class="hb-stat"><span class="hb-dot '+(aPagar.length?'due':'ok')+'"></span><b>'+aPagar.length+'</b><label>'+(aPagar.length?'a vencer':'já pagas')+' neste mês</label></div>'
    +'<div class="hb-stat"><span class="hb-dot '+(pagas.length?'ok':'mut')+'"></span><b>'+pagas.length+'</b><label>'+(pagas.length?'pagas':'ainda não pagas')+'</label></div>'
    +(proxima?'<div class="hb-stat"><span class="hb-dot mut"></span><b>'+chargeOf(proxima).tag+'</b><label>próxima cobrança: '+esc(proxima.nome)+'</label></div>':'')
    +'</div></div>';
  const rowHTML=(s,i)=>{
    const p=paid(s),ch=chargeOf(s);
    const charge=p?'<span class="pay-pill">Paga este mês</span>':'<span class="due-chip'+(ch.dd===0?' today':'')+'">'+ch.label+'</span>';
    const actions=(p?'':'<button class="btn pay-btn" onclick="openPayModal(\'sub\',\''+s.id+'\')">Pagar este mês</button>')+'<button class="icon-btn" onclick="openSubModal(\''+s.id+'\')" title="Editar" aria-label="Editar assinatura">'+PENCIL_SVG+'</button><button class="icon-btn" onclick="deleteSub(\''+s.id+'\')" title="Remover" aria-label="Remover assinatura">✕</button>';
    return '<div class="bill-row'+(p?' paid':'')+'" style="--i:'+i+'"><div class="bill-icon">'+brandOrCat(s.nome,s.categoria)+'</div><div class="bill-main"><div class="bill-name">'+esc(s.nome)+'</div><div class="bill-meta">'+esc(catInfo(s.categoria).nome)+', cobrada dia '+s.dia+'</div></div><div class="bill-charge">'+charge+'</div><div class="bill-price">'+fmtBRL(s.valor)+'</div><div class="bill-actions">'+actions+'</div></div>';
  };
  let html='';
  if(aPagar.length)html+='<div class="bsect"><div class="bsect-head"><h3>A pagar este mês</h3><span class="bsect-count">'+aPagar.length+'</span></div><div class="list-card">'+aPagar.map(rowHTML).join('')+'</div></div>';
  if(pagas.length)html+='<div class="bsect"><div class="bsect-head"><h3>Já pagas neste mês</h3><span class="bsect-count">'+pagas.length+'</span></div><div class="list-card">'+pagas.map((s,i)=>rowHTML(s,i+20)).join('')+'</div></div>';
  if(!subs.length)html=emptyStateHTML({icon:ES_REPEAT,title:'Nenhuma assinatura cadastrada',desc:'Adicione o primeiro serviço recorrente e acompanhe as cobranças aqui.',cta:'Nova assinatura',ctaOnclick:'openSubModal()'});
  document.getElementById('subsList').innerHTML=html;
}
function deleteSub(id){const s=state.subs.find(x=>x.id===id);if(!s)return;if(!confirm('Remover a assinatura "'+s.nome+'"?'))return;const snap=snapshotState();state.subs=state.subs.filter(x=>x.id!==id);saveState();renderAll();toast('Assinatura removida.',{action:()=>restoreState(snap)});}

/* ============ RENDAS / RECEBIMENTOS ============ */
const INCOME_KINDS={salario:{label:'Salário',cor:'#0ea5e9'},vale:{label:'Vale / Benefício',cor:'#a855f7'},outro:{label:'Outra entrada',cor:'#14b8a6'}};
const INC_ICON_SAL='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2.5" y="7" width="19" height="13" rx="2.5"/><path d="M8.5 7V5.6A2.6 2.6 0 0 1 11.1 3h1.8a2.6 2.6 0 0 1 2.6 2.6V7"/><path d="M2.5 12.5h19"/></svg>';
const INC_ICON_VALE='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="6" width="20" height="12" rx="2.5"/><circle cx="12" cy="12" r="2.4"/><path d="M6 12h.01M18 12h.01"/></svg>';
const INC_ICON_OUT='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="8" cy="8" r="5"/><path d="M18.09 10.37A6 6 0 1 1 10.34 18"/><path d="M7 8h2M8 7v2"/></svg>';
function incomeKind(inc){return INCOME_KINDS[(inc&&inc.tipo)||'outro']||INCOME_KINDS.outro;}
function incomeTile(inc){const k=incomeKind(inc);const ico=(inc&&inc.tipo)==='salario'?INC_ICON_SAL:((inc&&inc.tipo)==='vale'?INC_ICON_VALE:INC_ICON_OUT);return '<span class="cat-icon" style="background:'+k.cor+';color:'+iconColorFor(k.cor)+'">'+ico+'</span>';}
function incomeReceivedThisMonth(inc){const mk=currentMonthKey();return state.tx.some(t=>t.src==='income'&&t.srcId===inc.id&&monthKey(t.data)===mk);}
let editingIncomeId=null,selectedIncomeTipo='salario';
function setIncomeTipo(v){selectedIncomeTipo=v;document.querySelectorAll('#incTipoGrid .inc-kind-opt').forEach(o=>o.classList.toggle('sel',o.dataset.v===v));}
function setIncomeQuando(){const q=document.getElementById('incQuando').value;document.getElementById('incDiaField').style.display=q==='dia-fixo'?'block':'none';incomePreview();}
function incomePreview(){const el=document.getElementById('incPreview');if(!el)return;const quando=document.getElementById('incQuando').value;const dia=parseInt(document.getElementById('incDia').value)||1;const d=nextIncomeDate({quando,dia});const wd=d.toLocaleDateString('pt-BR',{weekday:'long'});el.textContent='Próximo recebimento: '+d.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric'})+' ('+wd+')';}
function openIncomeModal(id){
  if(!Array.isArray(state.incomes))state.incomes=[];
  const inc=id?state.incomes.find(i=>i.id===id):null;
  editingIncomeId=inc?inc.id:null;
  document.getElementById('incNome').value=inc?inc.nome:'';
  document.getElementById('incValor').value=inc?inc.valor:'';
  setIncomeTipo(inc?inc.tipo:'salario');
  document.getElementById('incQuando').value=inc?inc.quando:'quinto-dia-util';
  document.getElementById('incDia').value=(inc&&inc.quando==='dia-fixo')?inc.dia:'';
  document.getElementById('incomeModalTitle').textContent=inc?'Editar renda':'Nova renda';
  document.getElementById('incomeModalSub').textContent=inc?'Ajuste descrição, valor ou data de recebimento.':'Cadastre salário, vales e outras entradas fixas.';
  document.getElementById('incSaveBtn').textContent=inc?'Salvar alterações':'Salvar renda';
  setIncomeQuando();
  openModal('incomeOverlay');
}
function saveIncome(){
  const nome=document.getElementById('incNome').value.trim();
  const valor=parseFloat(document.getElementById('incValor').value);
  const quando=document.getElementById('incQuando').value;
  const dia=parseInt(document.getElementById('incDia').value);
  clearFieldErrors(document.getElementById('incomeOverlay'));
  let _bad=false;
  if(!nome){showFieldError(document.getElementById('incNome'),'Informe uma descrição.');_bad=true;}
  if(!valor||valor<=0){showFieldError(document.getElementById('incValor'),'Informe um valor válido.');_bad=true;}
  if(quando==='dia-fixo'&&(!dia||dia<1||dia>31)){showFieldError(document.getElementById('incDia'),'Informe um dia entre 1 e 31.');_bad=true;}
  if(_bad){toast('Verifique os campos destacados.','error');return;}
  const rec={nome,valor:Math.round(Math.abs(valor)*100)/100,tipo:selectedIncomeTipo,quando,dia:(quando==='dia-fixo'?dia:1)};
  if(!Array.isArray(state.incomes))state.incomes=[];
  if(editingIncomeId){const inc=state.incomes.find(x=>x.id===editingIncomeId);if(inc)Object.assign(inc,rec);toast('Renda atualizada.');}
  else{state.incomes.push(Object.assign({id:uid()},rec));toast('Renda adicionada.');}
  editingIncomeId=null;saveState();closeModal('incomeOverlay');renderAll();
}
function deleteIncome(id){const inc=(state.incomes||[]).find(x=>x.id===id);if(!inc)return;if(!confirm('Remover a renda "'+inc.nome+'"?'))return;const snap=snapshotState();state.incomes=state.incomes.filter(x=>x.id!==id);saveState();renderAll();toast('Renda removida.',{action:()=>restoreState(snap)});}
function renderRendas(){
  const list=(state.incomes||[]);
  const sub=document.getElementById('rendasSub'),sum=document.getElementById('rendasSummary'),box=document.getElementById('rendasList');
  if(!box)return;
  const totalMes=list.reduce((s,i)=>s+Math.abs(i.valor||0),0);
  const proxima=list.map(i=>({i,ni:incomeNext(i)})).sort((a,b)=>a.ni.dd-b.ni.dd)[0]||null;
  if(sub)sub.textContent=list.length?(list.length+' '+(list.length===1?'renda fixa':'rendas fixas')+', '+fmtBRL(totalMes)+' previstos por mês.'):'Cadastre salário, vales e outras entradas fixas para prever seus recebimentos.';
  const totKind=k=>list.filter(i=>i.tipo===k).reduce((s,i)=>s+Math.abs(i.valor||0),0);
  if(sum)sum.innerHTML='<div class="hero-bill"><div class="hb-main"><span class="hb-eyebrow">previsto por mês</span><span class="hb-total">'+fmtBRL(totalMes)+'</span><span class="hb-note">'+(proxima?('Próximo recebimento: '+esc(proxima.i.nome)+' · '+incomeNext(proxima.i).label+' ('+proxima.ni.date.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})+').'):'Adicione sua primeira renda para começar.')+'</span></div><div class="hb-side">'
    +'<div class="hb-stat"><span class="hb-dot ok"></span><b>'+fmtBRL(totKind('salario'))+'</b><label>em salário</label></div>'
    +'<div class="hb-stat"><span class="hb-dot mut"></span><b>'+fmtBRL(totKind('vale'))+'</b><label>em vales e benefícios</label></div>'
    +'<div class="hb-stat"><span class="hb-dot mut"></span><b>'+fmtBRL(totKind('outro'))+'</b><label>em outras entradas</label></div>'
    +'</div></div>';
  if(!list.length){box.innerHTML=emptyStateHTML({icon:ES_COINS,title:'Nenhuma renda cadastrada',desc:'Adicione salário, vales ou outras entradas fixas e veja quando cada valor cai.',cta:'Nova renda',ctaOnclick:'openIncomeModal()'});return;}
  const row=(inc,i)=>{
    const rec=incomeReceivedThisMonth(inc),ni=incomeNext(inc),k=incomeKind(inc);
    const charge=rec?'<span class="pay-pill">Recebido este mês</span>':'<span class="due-chip'+(ni.dd===0?' today':'')+'">'+ni.label+' · '+ni.date.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})+'</span>';
    const actions=(rec?'':'<button class="btn pay-btn" onclick="openPayModal(\'income\',\''+inc.id+'\')">Receber</button>')+'<button class="icon-btn" onclick="openIncomeModal(\''+inc.id+'\')" title="Editar" aria-label="Editar renda">'+PENCIL_SVG+'</button><button class="icon-btn" onclick="deleteIncome(\''+inc.id+'\')" title="Remover" aria-label="Remover renda">✕</button>';
    return '<div class="bill-row'+(rec?' paid':'')+'" style="--i:'+i+'"><div class="bill-icon">'+incomeTile(inc)+'</div><div class="bill-main"><div class="bill-name">'+esc(inc.nome)+'</div><div class="bill-meta">'+esc(k.label)+' · '+esc(incomeSchedLabel(inc))+'</div></div><div class="bill-charge">'+charge+'</div><div class="bill-price">'+fmtBRL(inc.valor)+'</div><div class="bill-actions">'+actions+'</div></div>';
  };
  let html='',ai=0;
  [['salario','Salário'],['vale','Vales e benefícios'],['outro','Outras entradas']].forEach(([key,label])=>{
    const items=list.filter(i=>i.tipo===key);
    if(!items.length)return;
    html+='<div class="bsect"><div class="bsect-head"><h3>'+label+'</h3><span class="bsect-count">'+items.length+'</span></div><div class="list-card">'+items.map(inc=>row(inc,ai++)).join('')+'</div></div>';
  });
  box.innerHTML=html;
}

function renderParcelas(){
  const now=new Date();const mk=currentMonthKey();
  const curStart=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-01';
  const paid=i=>!!i.pago||(i.data<curStart);
  const groups={};
  state.tx.filter(t=>t.parcelaInfo).forEach(t=>{const info=t.parcelaInfo;const g=info.grupo||('g-'+info.desc);if(!groups[g])groups[g]={desc:info.desc,total:info.total||1,valorTotal:info.valorTotal||0,itens:[]};groups[g].itens.push(t);});
  const entries=Object.values(groups).map(g=>{
    g.itens.sort((a,b)=>(a.parcelaInfo.atual||0)-(b.parcelaInfo.atual||0));
    if(!g.valorTotal)g.valorTotal=Math.round(g.itens.reduce((s,i)=>s+i.valor,0)*100)/100;
    return g;
  });
  const curOf=g=>g.itens.find(i=>monthKey(i.data)===mk)||null;
  const monthLabel=k=>capitalize(new Date(Number(k.slice(0,4)),Number(k.slice(5,7))-1,1).toLocaleDateString('pt-BR',{month:'short'}));
  const zones={aberto:[],done:[]};
  entries.forEach(g=>{(g.itens.every(paid)?zones.done:zones.aberto).push(g);});
  const dateKey=g=>{const c=curOf(g);return (c&&!paid(c))?'0'+c.data:((g.itens.find(i=>!paid(i))||{data:'2999-12-31'}).data);};
  zones.aberto.sort((a,b)=>dateKey(a).localeCompare(dateKey(b)));
  zones.done.sort((a,b)=>((b.itens[b.itens.length-1]||{}).data||'').localeCompare((a.itens[a.itens.length-1]||{}).data||''));
  let emAberto=0,pagasTot=0,restTot=0,mesAberto=0;
  entries.forEach(g=>{g.itens.forEach(i=>{if(paid(i))pagasTot++;else{emAberto+=i.valor;restTot++;}});const c=curOf(g);if(c&&!paid(c))mesAberto+=c.valor;});
  document.getElementById('parcelasSub').textContent=entries.length?(restTot?(restTot+' parcela'+(restTot===1?'':'s')+' a vencer, '+fmtBRL(emAberto)+' em aberto.'):'Todas as '+pagasTot+' parcelas pagas.'):'Nenhuma compra parcelada em andamento.';
  document.getElementById('parcelasSummary').innerHTML='<div class="hero-bill"><div class="hb-main"><span class="hb-eyebrow">'+(mesAberto?'a pagar neste mês':'em aberto hoje')+'</span><span class="hb-total">'+fmtBRL(mesAberto||emAberto)+'</span><span class="hb-note">'+(restTot?('No total, '+fmtBRL(emAberto)+' em aberto nas compras em andamento.'):'Nada em aberto no momento.')+'</span></div><div class="hb-side">'
    +'<div class="hb-stat"><span class="hb-dot ok"></span><b>'+pagasTot+'</b><label>parcelas pagas</label></div>'
    +'<div class="hb-stat"><span class="hb-dot mut"></span><b>'+restTot+'</b><label>a vencer</label></div>'
    +'<div class="hb-stat"><span class="hb-dot '+(entries.length?'due':'mut')+'"></span><b>'+entries.length+'</b><label>compras em andamento</label></div>'
    +'</div></div>';
  const card=(g,idx)=>{
    const c=curOf(g);
    const n=g.itens.length;
    const done=g.itens.every(paid);
    const pagasSay=g.itens.filter(paid).length;
    const target=!done&&c&&!paid(c)?c:null;
    const next=done?null:g.itens.find(i=>!paid(i));
    const steps=g.itens.map(i=>'<span class="step '+(paid(i)?'done':((i===c&&c&&!paid(c))?'now':'todo'))+'"></span>').join('<i class="conn"></i>');
    const meta=fmtBRL(g.valorTotal)+' em '+(g.total||n)+'x de '+fmtBRL(g.itens[0].valor);
    const chip=done?'<span class="par-chip">Concluída</span>':(c?'<span class="par-chip">Parcela '+(c.parcelaInfo.atual||1)+'<span class="of">/'+(c.parcelaInfo.total||n)+'</span></span>':'<span class="par-chip">Parcela</span>');
    let foot='',footRight='';
    if(target){
      foot='<div class="pc-txt"><span class="pc-label">Parcela deste mês</span><span class="pc-date">vence '+fmtDate(target.data)+'</span></div>';
      footRight='<div class="pc-amt">'+fmtBRL(target.valor)+'</div><button class="btn pay-btn" onclick="openPayModal(\'parcela\',\''+target.id+'\')">Pagar este mês</button>';
    }else if(done){
      foot='<div class="pc-txt"><span class="pc-label">Tudo pago</span><span class="pc-date">'+pagasSay+' de '+(g.total||n)+' parcelas, '+fmtBRL(g.valorTotal)+' no total</span></div>';
      footRight='<span class="pay-pill neutral">Concluída</span>';
    }else{
      const curPaid=c&&paid(c);
      foot='<div class="pc-txt"><span class="pc-label">'+(curPaid?'Parcela deste mês':'Próxima parcela')+'</span><span class="pc-date">'+(curPaid?('paga em '+fmtDate(c.data)):(next?('vence '+monthLabel(next.data.slice(0,7))+', '+fmtBRL(next.valor)):(''+n+'x concluídas')))+'</span></div>';
      footRight=curPaid?'<span class="pay-pill">Paga este mês</span>':(next?'':'<span class="pay-pill neutral">Concluída</span>');
    }
    const rest=Math.max(0,(g.total||n)-pagasSay);
    return '<div class="par-card'+(done?' done':'')+'" style="--i:'+idx+'"><div class="par-top"><div class="par-ico">'+brandOrCat(g.desc,(g.itens[0]||{}).categoria)+'</div><div class="par-txt"><div class="par-name">'+esc(g.desc)+'</div><div class="par-meta">'+meta+'</div></div>'+chip+'<button type="button" class="par-del" title="Excluir compra parcelada" aria-label="Excluir compra parcelada" onclick="deleteParcelaGrupo(\''+g.itens[0].id+'\')">'+TRASH_SVG+'</button></div><div class="steps-wrap"><div class="steps">'+steps+'</div><div class="steps-label"><b>'+pagasSay+'</b> de '+(g.total||n)+' pagas'+(done?'':', <b>'+rest+'</b> a vencer')+'</div></div><div class="par-cta">'+foot+footRight+'</div></div>';
  };
  let html='';
  if(zones.aberto.length)html+='<div class="bsect"><div class="bsect-head"><h3>Em aberto</h3><span class="bsect-count">'+zones.aberto.length+'</span></div><div class="grid-bills">'+zones.aberto.map((g,i)=>card(g,i)).join('')+'</div></div>';
  if(zones.done.length)html+='<div class="bsect"><div class="bsect-head"><h3>Já concluídas</h3><span class="bsect-count">'+zones.done.length+'</span></div><div class="grid-bills">'+zones.done.map((g,i)=>card(g,i+30)).join('')+'</div></div>';
  if(!entries.length)html=emptyStateHTML({icon:ES_LAYERS,title:'Nenhuma compra parcelada',desc:'Registre uma compra parcelada em Transações para acompanhar aqui.',cta:'Nova transação',ctaOnclick:'openTxModal()'});
  document.getElementById('parcelasGrid').innerHTML=html;
}
let pendingPay=null;
function initials(nome){const p=nome.trim().split(/\s+/);return ((p[0]?p[0].charAt(0):'')+(p[1]?p[1].charAt(0):'')).toUpperCase()||'—';}
function openPayModal(kind,id){
  if(!state.accounts.length){toast('Cadastre uma conta bancária antes de continuar.');openAccountModal();return;}
  pendingPay={kind,id};
  const list=document.getElementById('payAccList');
  const accListHTML=()=>state.accounts.map(a=>'<button type="button" class="pay-acc" data-id="'+a.id+'" onclick="pickPayAcc(this)"><span class="pa-tile">'+initials(a.nome)+'</span><span class="pa-main"><b>'+esc(a.nome)+'</b><span>'+ACCT_LABEL[a.tipo]+'</span></span><span class="pa-saldo'+(a.saldo<0?' neg':'')+'">'+fmtBRL(a.saldo)+'</span></button>').join('');
  if(kind==='income'){
    const inc=(state.incomes||[]).find(i=>i.id===id);if(!inc)return;
    document.getElementById('payTitle').textContent='Receber '+inc.nome;
    document.getElementById('paySub').textContent=incomeKind(inc).label+' · '+incomeSchedLabel(inc);
    document.getElementById('payAmt').textContent=fmtBRL(inc.valor);
    document.getElementById('payNote').textContent='O valor entra na conta escolhida e fica registrado nas Transações.';
    list.innerHTML=accListHTML();
    const first0=list.querySelector('.pay-acc');if(first0)pickPayAcc(first0);
    openModal('payOverlay');return;
  }
  const fis=kind==='sub'?state.subs.find(s=>s.id===id):state.tx.find(t=>t.id===id);
  if(!fis)return;
  document.getElementById('payTitle').textContent=kind==='sub'?('Pagar '+fis.nome):('Parcela '+fis.parcelaInfo.atual+'/'+fis.parcelaInfo.total);
  document.getElementById('paySub').textContent=kind==='sub'?('Assinatura mensal, cobrada dia '+fis.dia):fis.parcelaInfo.desc;
  document.getElementById('payAmt').textContent=fmtBRL(fis.valor);
  document.getElementById('payNote').textContent='O valor sai da conta escolhida e fica registrado nas Transações.';
  list.innerHTML=accListHTML();
  const first=list.querySelector('.pay-acc');
  if(first)pickPayAcc(first);
  openModal('payOverlay');
}
function pickPayAcc(el){document.querySelectorAll('.pay-acc').forEach(x=>{x.classList.toggle('sel',x===el);});}
function confirmPay(){
  const sel=document.querySelector('.pay-acc.sel');
  const acc=sel?state.accounts.find(a=>a.id===sel.getAttribute('data-id')):null;
  if(!acc){toast('Escolha a conta que vai pagar.');return;}
  const p=pendingPay;if(!p)return;pendingPay=null;
  if(p.kind==='income'){
    const inc=(state.incomes||[]).find(x=>x.id===p.id);if(!inc)return;
    if(incomeReceivedThisMonth(inc)){toast(inc.nome+' já foi recebido neste mês.');closeModal('payOverlay');renderAll();return;}
    const cat=inc.tipo==='salario'?'salario':(inc.tipo==='vale'?'bonus':'outros_renda');
    state.tx.push({id:uid(),desc:inc.nome,valor:-Math.abs(inc.valor),categoria:cat,tipo:'pix',contaId:acc.id,data:todayISO(),parcelaInfo:null,src:'income',srcId:inc.id});
    adjustBalance(acc.id,Math.abs(inc.valor));
    saveState();closeModal('payOverlay');renderAll();
    toast('Renda "'+inc.nome+'" recebida em '+acc.nome+'.');
  }else if(p.kind==='sub'){
    const s=state.subs.find(x=>x.id===p.id);if(!s)return;
    if(subPaidThisMonth(s)){toast(s.nome+' já está paga neste mês.');closeModal('payOverlay');renderAll();return;}
    state.tx.push({id:uid(),desc:s.nome,valor:s.valor,categoria:s.categoria,tipo:'debito',contaId:acc.id,data:todayISO(),parcelaInfo:null,src:'sub',srcId:s.id});
    adjustBalance(acc.id,-s.valor);
    saveState();closeModal('payOverlay');renderAll();
    toast(s.nome+' paga com '+acc.nome+'.');
  }else{
    const t=state.tx.find(x=>x.id===p.id);if(!t||!t.parcelaInfo)return;
    if(t.pago){toast('Essa parcela já foi paga.');closeModal('payOverlay');renderAll();return;}
    t.pago=true;
    state.tx.push({id:uid(),desc:'Pagamento de '+t.parcelaInfo.desc,valor:t.valor,categoria:t.categoria,tipo:'debito',contaId:acc.id,data:todayISO(),parcelaInfo:null,liq:true,src:'parcela',srcId:t.id});
    adjustBalance(acc.id,-t.valor);
    saveState();closeModal('payOverlay');renderAll();
    toast('Parcela '+t.parcelaInfo.atual+'/'+t.parcelaInfo.total+' paga com '+acc.nome+'.');
  }
}
function populateFilterOptions(){
  document.getElementById('fCategoria').innerHTML='<option value="">Todas categorias</option>'+allCats().map(c=>'<option value="'+esc(c.id)+'">'+esc(c.nome)+'</option>').join('');
  document.getElementById('fConta').innerHTML='<option value="">Todas contas/cartões</option>'+state.accounts.map(a=>'<option value="'+esc(a.id)+'">'+esc(a.nome)+'</option>').join('')+state.cards.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.nome)+'</option>').join('');
}
function clearFilters(){document.getElementById('fSearch').value='';document.getElementById('fCategoria').value='';document.getElementById('fTipo').value='';document.getElementById('fConta').value='';document.getElementById('fMes').value='';renderTransacoes();}
function renderTransacoes(){
  const search=document.getElementById('fSearch').value.toLowerCase(),cat=document.getElementById('fCategoria').value,tipo=document.getElementById('fTipo').value,conta=document.getElementById('fConta').value,mes=document.getElementById('fMes').value;
  const repIds=parcelGroupReps();
  const descOf=t=>(t.parcelaInfo&&t.parcelaInfo.desc)?t.parcelaInfo.desc:t.desc;
  let list=state.tx.map((t,o)=>({t,o,keep:!t.parcelaInfo||repIds.has(t.id)})).filter(x=>x.keep).sort((a,b)=>b.t.data.localeCompare(a.t.data)||b.o-a.o).map(x=>x.t);
  if(search)list=list.filter(t=>descOf(t).toLowerCase().includes(search));
  if(cat)list=list.filter(t=>t.categoria===cat);
  if(tipo)list=list.filter(t=>t.tipo===tipo);
  if(conta)list=list.filter(t=>t.contaId===conta);
  if(mes)list=list.filter(t=>monthKey(t.data)===mes);
  document.getElementById('txSub').textContent=list.length+' transaç'+(list.length===1?'ão':'ões')+' encontrada'+(list.length===1?'':'s')+'.';
  document.getElementById('txTableBody').innerHTML=list.map(t=>'<tr><td class="desc">'+esc(descOf(t))+'</td><td><span class="tag" style="border-color:'+catInfo(t.categoria).cor+'44;">'+esc(catInfo(t.categoria).nome)+'</span></td><td>'+(t.parcelaInfo?'Parcela '+t.parcelaInfo.atual+'/'+t.parcelaInfo.total:PAYTYPE_LABEL[t.tipo])+'</td><td>'+esc(accName(t.contaId))+'</td><td>'+fmtDate(t.data)+'</td><td class="val '+(t.valor<0?'pos':'')+'">'+(t.valor<0?'+':'')+fmtBRL(Math.abs(t.valor))+'</td><td><div class="row-actions"><button class="icon-btn" onclick="openTxModal(\''+t.id+'\')" title="Editar" aria-label="Editar transação">✎</button><button class="icon-btn" onclick="deleteTx(\''+t.id+'\')" title="Excluir" aria-label="Excluir transação">✕</button></div></td></tr>').join('')||'<tr><td colspan="7" style="text-align:center;color:var(--ink-faint);padding:40px;">Nenhuma transação encontrada com esses filtros.</td></tr>';
}
function deleteTx(id){
  const t=state.tx.find(x=>x.id===id);
  if(!confirm('Excluir a transação "'+(t?(t.desc||'Transação'):'')+'"?'))return;
  const snap=snapshotState();
  if(t)revertTxEffect(t);
  state.tx=state.tx.filter(x=>x.id!==id);
  saveState();renderAll();toast('Transação excluída.',{action:()=>restoreState(snap)});
}
function deleteParcelaGrupo(txId){
  const base=state.tx.find(t=>t.id===txId);
  if(!base||!base.parcelaInfo)return;
  const key=base.parcelaInfo.grupo||('g-'+base.parcelaInfo.desc);
  const items=state.tx.filter(t=>t.parcelaInfo&&((t.parcelaInfo.grupo||('g-'+t.parcelaInfo.desc))===key));
  if(!items.length)return;
  if(!confirm('Excluir a compra parcelada "'+(base.parcelaInfo.desc||'')+'" e suas '+items.length+' parcelas?'))return;
  const snap=snapshotState();
  state.tx=state.tx.filter(t=>!(t.parcelaInfo&&((t.parcelaInfo.grupo||('g-'+t.parcelaInfo.desc))===key)));
  saveState();renderAll();
  toast('Compra parcelada excluída.',{action:()=>restoreState(snap)});
}
['fSearch','fCategoria','fTipo','fConta','fMes'].forEach(id=>{document.getElementById(id).addEventListener('input',renderTransacoes);document.getElementById(id).addEventListener('change',renderTransacoes);});

const FOCUSABLE_SEL='a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
function getFocusable(root){
  if(!root)return [];
  return Array.prototype.slice.call(root.querySelectorAll(FOCUSABLE_SEL)).filter(el=>!(el.hidden||el.getAttribute('aria-hidden')==='true')&&(el.offsetWidth>0||el.offsetHeight>0||el.getClientRects().length>0||el===document.activeElement));
}
function activeDialog(){
  const ov=document.querySelector('.overlay.open .modal');
  if(ov)return ov;
  const fat=document.getElementById('faturaOverlay');
  if(fat&&!fat.hidden)return fat.querySelector('.cc-modal');
  return null;
}
function openModal(id){
  const m=document.getElementById(id);if(!m)return;
  clearFieldErrors(m);
  if(!m._prevFocus)m._prevFocus=document.activeElement;
  m.classList.add('open');
  const f=getFocusable(m)[0]||m.querySelector('.modal');
  if(f&&f.focus){try{f.focus({preventScroll:true});}catch(e){try{f.focus();}catch(e2){}}}
}
function restoreFocus(prev){
  if(prev&&prev!==document.body&&prev.focus){try{prev.focus({preventScroll:true});}catch(e){try{prev.focus();}catch(e2){}}}
}
function closeModal(id){
  const m=document.getElementById(id);if(!m)return;
  m.classList.remove('open');
  const p=m._prevFocus;m._prevFocus=null;
  restoreFocus(p);
  if(document.activeElement&&document.activeElement!==document.body&&m.contains(document.activeElement))document.activeElement.blur();
}
document.querySelectorAll('.overlay').forEach(o=>{o.addEventListener('click',e=>{if(e.target===o)closeModal(o.id);});});
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'){
    const openOv=document.querySelector('.overlay.open');
    if(openOv){closeModal(openOv.id);return;}
    const fat=document.getElementById('faturaOverlay');
    if(fat&&!fat.hidden){closeFaturaModal();return;}
  }
  if(e.key!=='Tab')return;
  const scope=activeDialog();
  if(!scope)return;
  const fs=getFocusable(scope);
  if(!fs.length){e.preventDefault();return;}
  const first=fs[0],last=fs[fs.length-1],ae=document.activeElement;
  if(!scope.contains(ae)){e.preventDefault();(e.shiftKey?last:first).focus();return;}
  if(e.shiftKey&&ae===first){e.preventDefault();last.focus();}
  else if(!e.shiftKey&&ae===last){e.preventDefault();first.focus();}
});

