    let pt=tx.parcelaInfo?'parcelado':tx.tipo;
    if(txDirection==='entrada'&&['credito','parcelado','boleto'].includes(pt))pt='pix';
    if(pt==='parcelado'){setPayType('parcelado');document.getElementById('txParcelas').value=tx.parcelaInfo.total;}
    else{setPayType(pt);document.getElementById('txParcelas').value=2;}
