function saveSub(){
  const nome=document.getElementById('subNome').value.trim(),valor=parseFloat(document.getElementById('subValor').value),dia=parseInt(document.getElementById('subDia').value),categoria=document.getElementById('subCategoria').value;
  clearFieldErrors(document.getElementById('subOverlay'));
  let _bad=false;
  if(!nome){showFieldError(document.getElementById('subNome'),'Informe o serviço.');_bad=true;}
  if(!valor){showFieldError(document.getElementById('subValor'),'Informe o valor.');_bad=true;}
  if(!dia){showFieldError(document.getElementById('subDia'),'Informe o dia de cobrança.');_bad=true;}
  if(_bad){toast('Verifique os campos destacados.','error');return;}
  if(editingSubId){
    const s=state.subs.find(x=>x.id===editingSubId);
    if(s){s.nome=nome;s.valor=valor;s.dia=dia;s.categoria=categoria;toast('Assinatura atualizada.');}
  }else{
    state.subs.push({id:uid(),nome,valor,dia,categoria});
    toast('Assinatura adicionada.');
  }
  editingSubId=null;saveState();closeModal('subOverlay');renderAll();
}

function openSettingsModal(){document.getElementById('brapiToken').value=state.brapiToken||'';openModal('settingsOverlay');}
function saveSettings(){state.brapiToken=document.getElementById('brapiToken').value.trim();saveState();closeModal('settingsOverlay');toast('Configurações salvas.');loadMarketData();}
function sanitizeStr(v,max){return (v==null?'':String(v)).replace(/[\u0000-\u001f\u007f]/g,'').trim().slice(0,typeof max==='number'?max:120);}
function sanitizeNum(v,def){const n=typeof v==='number'?v:parseFloat(String(v==null?'':v).replace(',','.'));return Number.isFinite(n)?n:(def||0);}
function sanitizeDate(v){const s=sanitizeStr(v,10);return /^\d{4}-\d{2}-\d{2}$/.test(s)?s:'';}
function sanitizeColor(v){const s=sanitizeStr(v,32);return /^#[0-9A-Fa-f]{3,8}$/.test(s)?s:'#9CA3AF';}
function sanitizeState(raw){
  raw=(raw&&typeof raw==='object')?raw:{};
  const out=emptyState();
  const S=(v,n)=>sanitizeStr(v,n),N=(v,d)=>sanitizeNum(v,d),D=v=>sanitizeDate(v),ID=v=>safeId(v);
  const arr=(v,max)=>Array.isArray(v)?v.slice(0,max):[];
  out.accounts=arr(raw.accounts,500).map(a=>a&&typeof a==='object'?({id:ID(a.id),nome:S(a.nome,80)||'Conta',tipo:S(a.tipo,20)||'corrente',saldo:N(a.saldo,0)}):null).filter(Boolean);
  const accIds=new Set(out.accounts.map(a=>a.id));
  out.cards=arr(raw.cards,500).map(c=>c&&typeof c==='object'?({id:ID(c.id),nome:S(c.nome,80)||'Cartão',banco:S(c.banco,60),limite:N(c.limite,0),fatura:N(c.fatura,0),fechamento:Math.min(28,Math.max(1,parseInt(c.fechamento,10)||10)),vencimento:Math.min(28,Math.max(1,parseInt(c.vencimento,10)||15)),cor:sanitizeColor(c.cor)}):null).filter(Boolean);
  const cardIds=new Set(out.cards.map(c=>c.id));
  const validRef=id=>{const s=safeId(id);return (accIds.has(s)||cardIds.has(s))?s:null;};
  out.subs=arr(raw.subs,500).map(s=>s&&typeof s==='object'?({id:ID(s.id),nome:S(s.nome,80)||'Assinatura',valor:N(s.valor,0),dia:Math.min(31,Math.max(1,parseInt(s.dia,10)||1)),categoria:S(s.categoria,40)||'assinaturas'}):null).filter(Boolean);
  const INC_TIPOS=['salario','vale','outro'],INC_QUANDO=['quinto-dia-util','ultimo-dia','dia-fixo'];
  out.incomes=arr(raw.incomes,300).map(i=>i&&typeof i==='object'?({id:ID(i.id),nome:S(i.nome,80)||'Renda',valor:Math.abs(N(i.valor,0)),tipo:(INC_TIPOS.indexOf(i.tipo)>=0?i.tipo:'outro'),quando:(INC_QUANDO.indexOf(i.quando)>=0?i.quando:'dia-fixo'),dia:Math.min(31,Math.max(1,parseInt(i.dia,10)||1))}):null).filter(Boolean);
  out.cats=arr(raw.cats,200).map(c=>c&&typeof c==='object'?({id:'cat_'+safeId(String(c.id||'').replace(/^cat_/,'')),nome:S(c.nome,40)||'Categoria',cor:sanitizeColor(c.cor)}):null).filter(Boolean);
  const TYPES=['debito','credito','boleto','parcelado','recebimento'];
  out.tx=arr(raw.tx,20000).map(t=>{
    if(!t||typeof t!=='object')return null;
    const pi=(t.parcelaInfo&&typeof t.parcelaInfo==='object')?{grupo:safeId(t.parcelaInfo.grupo),atual:Math.max(1,parseInt(t.parcelaInfo.atual,10)||1),total:Math.max(1,parseInt(t.parcelaInfo.total,10)||1),desc:S(t.parcelaInfo.desc,120),valorTotal:N(t.parcelaInfo.valorTotal,0)}:null;
    const o={id:ID(t.id),desc:S(t.desc,140),valor:N(t.valor,0),categoria:S(t.categoria,40),tipo:TYPES.indexOf(t.tipo)>=0?t.tipo:'debito',contaId:validRef(t.contaId),data:D(t.data)||todayISO(),parcelaInfo:pi,liq:!!t.liq};
    if(t.src!=null)o.src=S(t.src,20);
    if(t.srcId!=null)o.srcId=safeId(t.srcId);
    return o;
  }).filter(Boolean);
  out.watchlist=arr(raw.watchlist,100).map(x=>S(x,12).toUpperCase().replace(/[^A-Z0-9.]/g,'')).filter(Boolean);
  if(!out.watchlist.length)out.watchlist=['PETR4','VALE3','ITUB4','MGLU3'];
  out.brapiToken=S(raw.brapiToken,120);
  out.nome=S(raw.nome,80);
  out.moeda=S(raw.moeda,8)||'BRL';
  out.diaSalario=raw.diaSalario==null?null:(Math.min(31,Math.max(1,parseInt(raw.diaSalario,10)||0))||null);
  out.objetivo=S(raw.objetivo,40);
  out.rendaLiquido=N(raw.rendaLiquido,0);
  out.frequencia=S(raw.frequencia,20)||'mensal';
  out.dataRecebimento=D(raw.dataRecebimento);
  out.rendaVariavel=N(raw.rendaVariavel,0);
  out.contas=arr(raw.contas,50);
  out.cartoes=arr(raw.cartoes,50);
  out.parcelas=arr(raw.parcelas,200);
  const g=(raw.gastos&&typeof raw.gastos==='object')?raw.gastos:{};
  out.gastos={assinaturas:arr(g.assinaturas,200),fixos:arr(g.fixos,200),variaveis:arr(g.variaveis,200)};
  const ob=(raw.objetivos&&typeof raw.objetivos==='object')?raw.objetivos:{};
  out.objetivos={metaEconomizar:N(ob.metaEconomizar,0),metaReserva:N(ob.metaReserva,0),objetivoFuturo:S(ob.objetivoFuturo,60),prazoObjetivo:S(ob.prazoObjetivo,40),minimoDisponivel:N(ob.minimoDisponivel,0)};
  return out;
}
function validateBackupData(d){
  if(!d||typeof d!=='object')return false;
  const st=(d.state&&typeof d.state==='object')?d.state:(d.accounts||d.cards||d.tx?d:null);
  return !!(st&&Array.isArray(st.accounts)&&Array.isArray(st.cards)&&Array.isArray(st.tx)&&Array.isArray(st.subs));
}
function extractBackupState(d){return (d.state&&typeof d.state==='object')?d.state:d;}
function exportBackup(){
  try{
    const payload={app:'financas',version:2,appVersion:APP_VERSION,exportedAt:new Date().toISOString(),state:state};
    const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});
    const a=document.createElement('a');
    a.href=URL.createObjectURL(blob);
    a.download='financas-backup-'+new Date().toISOString().slice(0,10)+'.json';
    document.body.appendChild(a);a.click();
    setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},500);
    toast('Backup exportado.');
  }catch(e){console.error('Falha ao exportar backup:',e);toastError('Não foi possível exportar o backup.');}
}
function importBackupFile(input){
  const f=input&&input.files&&input.files[0];
  if(!f)return;
  const rd=new FileReader();
  rd.onload=()=>{
    try{
      const d=JSON.parse(rd.result);
      if(!validateBackupData(d)){toastError('Arquivo inválido: não é um backup deste aplicativo.');input.value='';return;}
      const clean=sanitizeState(extractBackupState(d));
      const n=(clean.tx||[]).length;
      if(confirm('Substituir todos os dados atuais pelo backup ('+n+' transações)? Esta ação não pode ser desfeita.')){
        const snap=snapshotState();
        state=clean;
        saveState();
        try{closeModal('settingsOverlay');}catch(e){}
        renderAll();
        toast('Backup restaurado.',{action:()=>restoreState(snap)});
      }
    }catch(e){console.error('Falha ao importar backup:',e);toastError('Arquivo inválido: não foi possível ler.');}
    input.value='';
  };
  rd.onerror=()=>{console.error('Erro de leitura do arquivo de backup.');toastError('Não foi possível ler o arquivo.');input.value='';};
  rd.readAsText(f);
}

/* ============ API MODULE ============ */
const API_CACHE_KEY='cofre_api_cache_v1';
function loadCache(key){try{const raw=localStorage.getItem(API_CACHE_KEY);if(!raw)return null;const all=JSON.parse(raw);return all[key]||null;}catch(e){return null;}}
function saveCache(key,data){try{const raw=localStorage.getItem(API_CACHE_KEY);const all=raw?JSON.parse(raw):{};all[key]={data,timestamp:Date.now()};localStorage.setItem(API_CACHE_KEY,JSON.stringify(all));}catch(e){}}
function isCacheFresh(key,ttlMs){const c=loadCache(key);return c&&(Date.now()-c.timestamp<ttlMs);}

async function fetchBCBSeries(code,n){
  const url='https://api.bcb.gov.br/dados/serie/bcdata.sgs.'+code+'/dados/ultimos/'+n+'?formato=json';
  const res=await fetch(url);if(!res.ok)throw new Error('BCB fetch failed');
  return await res.json();
}

async function fetchBrapiQuote(ticker,token){
  let url='https://brapi.dev/api/quote/'+encodeURIComponent(ticker);
  if(token)url+='?token='+encodeURIComponent(token);
  const res=await fetch(url);if(!res.ok)throw new Error('brapi fetch failed');
  const json=await res.json();
  return json.results&&json.results[0]?json.results[0]:null;
}

async function loadMacroData(){
  if(isCacheFresh('macro',6*60*60*1000))return loadCache('macro').data;
  const result={};
  try{
    const selicData=await fetchBCBSeries(432,1);
    if(selicData&&selicData.length){result.selic=selicData[selicData.length-1].valor;result.selicDate=selicData[selicData.length-1].data;}
  }catch(e){console.warn('Falha ao buscar Selic, usando cache:',e);const c=loadCache('macro');if(c&&c.data.selic){result.selic=c.data.selic;result.selicDate=c.data.selicDate;}}
  try{
    const ipcaData=await fetchBCBSeries(433,1);
    if(ipcaData&&ipcaData.length){result.ipca=ipcaData[ipcaData.length-1].valor;result.ipcaDate=ipcaData[ipcaData.length-1].data;}
  }catch(e){console.warn('Falha ao buscar IPCA, usando cache:',e);const c=loadCache('macro');if(c&&c.data.ipca){result.ipca=c.data.ipca;result.ipcaDate=c.data.ipcaDate;}}
  try{
    const usdData=await fetchBCBSeries(10813,1);
    if(usdData&&usdData.length){result.usd=usdData[usdData.length-1].valor;result.usdDate=usdData[usdData.length-1].data;}
  }catch(e){console.warn('Falha ao buscar PTAX, usando cache:',e);const c=loadCache('macro');if(c&&c.data.usd){result.usd=c.data.usd;result.usdDate=c.data.usdDate;}}
  if(result.selic||result.usd)saveCache('macro',result);
  return result;
}

async function loadWatchlistData(){
  const watchlist=state.watchlist||['PETR4','VALE3','ITUB4','MGLU3'];
  if(isCacheFresh('watchlist_'+watchlist.join(','),30*60*1000))return loadCache('watchlist_'+watchlist.join(',')).data;
  const results=[];
  for(const ticker of watchlist){
    try{
      const q=await fetchBrapiQuote(ticker,state.brapiToken);
      if(q)results.push(q);
    }catch(e){console.warn('Falha ao buscar cotação de '+ticker+':',e);}
  }
  if(results.length)saveCache('watchlist_'+watchlist.join(','),results);
  return results;
}

let macroCache={};
async function loadMarketData(){
  try{
    const macro=await loadMacroData();
    macroCache=macro;
    macroLoaded=true;
    const el1=document.getElementById('dashMacro1');
    const el2=document.getElementById('dashMacro2');
    if(el1)el1.innerHTML='<div class="mac-label">Taxa Selic</div><div class="mac-val">'+esc(macro.selic||'--')+'%</div><div class="mac-sub">'+(macro.selicDate?'Meta Copom · '+esc(macro.selicDate):'Indisponível')+'</div>';
    if(el2)el2.innerHTML='<div class="mac-label">Dólar PTAX</div><div class="mac-val">R$ '+esc(macro.usd||'--')+'</div><div class="mac-sub">'+(macro.usdDate?'Câmbio · '+esc(macro.usdDate):'Indisponível')+'</div>';
  }catch(e){console.error('Falha ao carregar dados macro:',e);macroLoaded=true;}

  renderMacroPage();
  renderWatchlist();
}

function renderMacroPage(){
  const row=document.getElementById('macroRow');if(!row)return;
  const m=macroCache;
  if(macroLoaded&&!m.selic&&!m.ipca&&!m.usd){
    row.innerHTML='<div style="grid-column:1/-1;">'+marketErrorHTML({title:'Indicadores indisponíveis',desc:'Não conseguimos carregar Selic, IPCA e Dólar agora. Verifique sua conexão.'})+'</div>';
    return;
  }
  row.innerHTML=`
    <div class="macro-card fade-in">
      <div class="macro-label">Taxa Selic</div>
      <div class="macro-val">${esc(m.selic)||'--'}%</div>
      <div class="macro-sub">${m.selicDate?'Meta definida pelo Copom · '+esc(m.selicDate):'Carregando...'}</div>
    </div>
    <div class="macro-card fade-in">
      <div class="macro-label">IPCA acumulado 12m</div>
      <div class="macro-val">${m.ipca?esc(m.ipca)+'%':'--'}</div>
      <div class="macro-sub">${m.ipcaDate?'IBGE · '+esc(m.ipcaDate):'Carregando...'}</div>
    </div>
    <div class="macro-card fade-in">
      <div class="macro-label">Dólar PTAX</div>
      <div class="macro-val">R$ ${esc(m.usd)||'--'}</div>
      <div class="macro-sub">${m.usdDate?'Câmbio de venda · '+esc(m.usdDate):'Carregando...'}</div>
    </div>
  `;
}

async function renderWatchlist(){
  const body=document.getElementById('watchlistBody');if(!body)return;
  const watchlist=state.watchlist||[];
  document.getElementById('watchlistSub').textContent=watchlist.length+' ativo'+(watchlist.length===1?'':'s')+' monitorado'+(watchlist.length===1?'':'s')+'.';
  if(!watchlist.length){body.innerHTML='<tr><td colspan="7">'+emptyStateHTML({compact:true,icon:ES_TRENDING,title:'Nenhum ativo monitorado',desc:'Adicione um ticker (ex.: PETR4) para acompanhar cotações em tempo real.',cta:'Adicionar ativo',ctaOnclick:"document.getElementById('addTickerInput').focus()"})+'</td></tr>';return;}
  body.innerHTML='<tr><td colspan="7" style="text-align:center;color:var(--ink-faint);padding:30px;">Carregando cotações...</td></tr>';
  try{
    const data=await loadWatchlistData();
    if(!data||!data.length){body.innerHTML='<tr><td colspan="7">'+marketErrorHTML({title:'Sem cotações agora',desc:'Não recebemos os dados de mercado. Verifique sua conexão e tente novamente.'})+'</td></tr>';return;}
    body.innerHTML=data.map(q=>{
      const change=q.regularMarketChange||0;const changePct=q.regularMarketChangePercent||0;
      const isUp=change>=0;const mc=q.marketCap?(q.marketCap>=1e9?(q.marketCap/1e9).toFixed(1)+'B':q.marketCap>=1e6?(q.marketCap/1e6).toFixed(0)+'M':'--'):'--';
      return '<tr><td class="desc" style="font-family:\'Inter\',sans-serif;">'+esc(q.symbol)+'</td><td>'+esc(q.shortName||q.longName||'')+'</td><td class="val">R$ '+(q.regularMarketPrice||0).toFixed(2)+'</td><td class="val '+(isUp?'pos':'neg')+'">'+(isUp?'+':'')+change.toFixed(2)+'</td><td class="val '+(isUp?'pos':'neg')+'">'+(isUp?'+':'')+changePct.toFixed(2)+'%</td><td style="text-align:right;color:var(--ink-dim);">R$ '+mc+'</td><td><div class="row-actions"><button class="icon-btn" onclick="removeFromWatchlist(\''+esc(q.symbol)+'\')" title="Remover" aria-label="Remover ativo">✕</button></div></td></tr>';
    }).join('');
  }catch(e){console.error('Falha ao carregar cotações:',e);body.innerHTML='<tr><td colspan="7">'+marketErrorHTML({title:'Falha ao carregar cotações',desc:'Não foi possível conectar ao serviço de cotações. Verifique sua internet.'})+'</td></tr>';}
}

function addToWatchlist(){
  const input=document.getElementById('addTickerInput');const ticker=input.value.trim().toUpperCase().replace(/[^A-Z0-9.]/g,'').slice(0,12);
  if(!ticker)return;
  if(!state.watchlist)state.watchlist=['PETR4','VALE3','ITUB4','MGLU3'];
  if(state.watchlist.includes(ticker)){toast('Ativo já está na watchlist.');return;}
  state.watchlist.push(ticker);saveState();input.value='';toast(ticker+' adicionado à watchlist.');loadMarketData();
}
function removeFromWatchlist(ticker){state.watchlist=(state.watchlist||[]).filter(t=>t!==ticker);saveState();toast(ticker+' removido.');loadMarketData();}
document.getElementById('addTickerInput').addEventListener('keydown',e=>{if(e.key==='Enter')addToWatchlist();});

